 mutable std::vector<std::string>trace;std::vector<Instance*>live;std::vector<MaterialProxyBindingCandidate>bindings;unsigned next=0;
 MaterialProxyInstanceCandidate*create(const std::string&name)override{auto id=++next;trace.push_back("C "+std::to_string(id)+" "+name);if(name=="Missing")return nullptr;gate(name=="Bind","controlled caller service name");auto*p=new Instance(*this,id);try{live.push_back(p);}catch(...){delete p;throw;}return p;}
